// Module-level GUID matcher — used wherever a lookup value must never be shown
// as a display name (client-name backfill in getRecords / getRecordDetail).
const GUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// ── Postgres user helpers ─────────────────────────────────────────────────────
// These replace the old core2.dbo.AspNetUsers queries. SQL Server stays for all
// business data (projects, allocations, org hierarchy) — only identity moves here.

/** All users for a tenant (including deleted) keyed by lowercase id. */
async function appUsersMap(tenantId: string): Promise<Map<string, UserRow>> {
  const rows = await getUsersByTenant(tenantId);
  return new Map(rows.map(u => [u.id.toLowerCase(), u]));
}

/** Live single-user org/access snapshot for the Edit Staff modal. Reads the
 *  app users table directly (no route/provider caches) so a long-open browser
 *  tab re-seeds the popup from the person's CURRENT row, not the stale in-tab
 *  copy it opened from. Returns null for unknown/deleted users. */
export async function getStaffCoreRds(tenantId: string, guid: string): Promise<Record<string, string> | null> {
  const u = (await appUsersMap(tenantId)).get(guid.toLowerCase());
  if (!u || u.deleted) return null;
  return {
    id: u.id,
    name: u.name ?? "",
    username: u.username ?? "",
    divisionId: u.divisionId == null ? "" : String(u.divisionId),
    departmentId: u.departmentId == null ? "" : String(u.departmentId),
    roleId: u.roleId == null ? "" : String(u.roleId),
    jobTitleId: u.jobTitleId == null ? "" : String(u.jobTitleId),
    // Same precedence as the staff grid rows: the site-admin flag wins.
    accessLevel: u.isSiteAdmin ? "admin" : (u.accessLevel ?? ""),
    employeeType: u.employeeType ?? "",
    phoneNumber: u.phoneNumber ?? "",
  };
}

/** Active (non-deleted) users for a tenant keyed by lowercase id. */
async function appActiveUsersMap(tenantId: string): Promise<Map<string, UserRow>> {
  const rows = await getActiveUsersByTenant(tenantId);
  return new Map(rows.map(u => [u.id.toLowerCase(), u]));
}

/** Resolve a list of GUIDs → display name from Postgres users. */
async function appResolveNames(guids: string[], tenantId: string): Promise<Map<string, string>> {
  if (!guids.length) return new Map();
  const lower = [...new Set(guids.map(g => g.toLowerCase()))].filter(Boolean);
  if (!lower.length) return new Map();
  const rows = await getUsersByTenantAndIds(tenantId, lower);
  return new Map(rows.map(r => [r.id.toLowerCase(), r.name]));
}

// ── Placeholder-aware display titles ─────────────────────────────────────────
// Some onboardings stamp a generic filler ("Staff", "Employee", …) into
// users.title (and even into the JobTitle catalogue) while the person's REAL
// role lives in users.role. A placeholder title must never win over a specific
// role, or whole tenants collapse into one "Staff" bucket on Forecast/Resources.
// Only treated as a placeholder when a more specific value exists to fall back
// to — a tenant where "Staff" genuinely IS everyone's title and role keeps
// rendering "Staff".
const TITLE_PLACEHOLDERS = new Set([
  "staff", "employee", "user", "member", "unassigned", "null",
  "n/a", "na", "none", "-", "unknown", "tbd",
]);
function isTitlePlaceholder(s: string | null | undefined): boolean {
  const t = (s ?? "").trim().toLowerCase();
  return !t || TITLE_PLACEHOLDERS.has(t);
}
/** Display title for a person: first NON-placeholder of title → role; if
 *  everything is a placeholder, keep the original so display never regresses. */
export function realTitleOf(title: string | null | undefined, role: string | null | undefined): string {
  const t = (title ?? "").trim();
  const r = (role ?? "").trim();
  return (!isTitlePlaceholder(t) ? t : "") || (!isTitlePlaceholder(r) ? r : "") || t || r;
}

/** Map a Postgres UserRow to the legacy AspNetUsers column shape expected by
 *  downstream processing loops. Keeps field names identical so the existing
 *  personRec-building code needs no renaming. */
function appUserToLegacy(u: UserRow): Record<string, unknown> {
  const dispTitle = realTitleOf(u.title, u.role);
  return {
    Id: u.id,
    UserName: u.username,
    Name: u.name,
    Title: dispTitle,
    JobTitleName: dispTitle,     // resolveRole: prefers JobTitleName, falls back to Title
    RoleNm: u.role,              // resolveRoleName: prefers RoleNm
    UserRoleTxt: u.role,         // resolveRoleName fallback
    BuChoice: u.businessUnit,    // CRMBusinessUnitChoice text
    DivisionLookup: u.divisionId,
    DepartmentLookup: u.departmentId,
    GlobalRoleID: u.roleId,
    JobTitleLookup: u.jobTitleId,
    IsSiteAdmin: u.isSiteAdmin ? 1 : 0,
    IsDefaultAdmin: 0,
    IsManager: u.isManager ? 1 : 0,
    UserRoleIdLookup: u.accessLevel,
    UGITStartDate: u.startDate,
    UGITEndDate: u.endDate,
    EmployeeType: u.employeeType,
    PhoneNumber: u.phoneNumber,
    EmployeeId: u.employeeId,
    Office: u.office,
    Email: u.email,
    // null (legacy/imported) counts as verified; only an explicit false flags red.
    EmailConfirmed: u.emailConfirmed,
    // Org-name columns (formerly from SQL JOINs) — left null; the downstream
    // code falls back to divisionHierarchy() for DivTitle and to empty string
    // for DeptNm. Role/JobTitle rates are handled by the rbdRateMap below.
    DivTitle: null as string | null,
    DivShort: null as string | null,
    DeptNm: null as string | null,
    DeptDivId: null as string | null,
    JtBilling:   null as number | null,
    JtCost:      null as number | null,
    RoleBilling: null as number | null,
    RoleLabor:   null as number | null,
    RoleCost:    null as number | null,
  };
}

// ── Unified staff + org-chain map (cached, tenant-scoped) ────────────────────
// Resolves the full org chain (JobTitle → Department → Division → BU) for every
// active staff member in ONE SQL query against core2, then joins with user data
// from the app DB. Replaces the per-function pattern of calling appActiveUsersMap
// + building jtDeptMaps inline + calling divisionHierarchy separately.
export interface StaffOrgEntry {
  id: string; name: string; username: string; email: string;
  /** Canonical app-user lifecycle state, retained for historical team rows. */
  enabled: boolean;
  title: string; role: string;
  jobTitleId: string; divisionId: string; departmentId: string;
  // resolved display names (from core2 org tables)
  dept: string;     // Department.Title
  divName: string;  // CompanyDivisions display name (ShortName preferred)
  buName: string;   // BusinessUnit.Title
  // Employee type from the app-DB users table ("Full-Time", "Part-Time",
  // "As Needed", "Temporary", "SCA Contingency Staff", or "" when unknown).
  // Carried so team views can color names by employment type.
  employeeType: string;
  // Resolved org-unit IDs (lowercase, "" when unknown) — the JobTitle chain
  // wins, user-row Division/Department lookups are the fallback. These back
  // the org-audience sentinel ids ("org:bu:<id>" etc.), so they must resolve
  // the SAME way the display names above do.
  orgBuId: string;
  orgDivId: string;
  orgDeptId: string;
  // Live role-audience sentinel ids ("role:<roleGuid>", lowercase): every
  // tenant Roles row whose normalized Name equals this user's role name.
  // Duplicate same-named Roles rows ALL emit, so a rule saved with either
  // twin GUID matches everyone displaying that role name (see role-audience.ts).
  roleAudienceIds: string[];
}
const staffOrgCache = new Map<string, { map: Map<string, StaffOrgEntry>; exp: number }>();
const STAFF_ORG_TTL_MS = 5 * 60_000;
// Generation counter, bumped on EVERY invalidation: a background serve-stale
// rebuild that started before a bust must never write its pre-bust map back
// (import/org writes rely on the bust taking effect immediately). Global (not
// per-tenant) — a discarded cross-tenant write just rebuilds on next read.
let staffOrgGen = 0;
export function invalidateStaffOrgCache(tid?: string): void {
  staffOrgGen++;
  if (tid) staffOrgCache.delete(tid);
  else staffOrgCache.clear();
}

// ── Live audience sentinel ids: org units + roles ────────────────────────────
// "org:bu:<id>" / "org:div:<id>" / "org:dept:<id>" — BU/Division/Department
// audiences, resolved from the SAME org chain the display names use
// (appStaffOrgMap), so what an admin sees on a staff card is exactly what a
// rule matches. "role:<roleGuid>" — role audiences, resolved from the same
// map via the role-name bridge (role-audience.ts): users match every Roles
// row sharing their displayed role name. One resolver set carries BOTH
// families, so every consumer (nav visibility, stage rules, skip exempts,
// capabilities groupIds, bulk user lists) gains role audiences in lockstep.
/** Tenant label → tenant GUID. LOCKSTEP with pipeline.ts resolveTenantId —
 *  same namespace, same lowercase rule (duplicated here to avoid importing
 *  pipeline.ts, which imports this module). */
const TENANT_GUID_RE_ORG = /^[0-9a-fA-F-]{36}$/;
const TENANT_NAMESPACE_ORG = "5d8f1e6a-2c3b-4d7e-9a1f-0b2c3d4e5f6a";
export function tenantLabelToTid(raw: string): string {
  const v = (raw ?? "").trim();
  return TENANT_GUID_RE_ORG.test(v) ? v : uuidv5(v.toLowerCase(), TENANT_NAMESPACE_ORG);
}
/** The org sentinel ids one user belongs to (lowercase). Empty set when the
 *  user is unknown or has no resolvable org placement. */
export async function orgAudienceIdsForUser(tid: string, userId: string | null | undefined): Promise<Set<string>> {
  return (await orgAudienceIdsForUserChecked(tid, userId)) ?? new Set();
}
/** Tri-state variant: null = the org chain could not be loaded (DB outage) —
 *  distinct from "user is in no org units". "except"-mode audience checks
 *  need this so an outage never makes everyone look excluded-from-nothing. */
export async function orgAudienceIdsForUserChecked(tid: string, userId: string | null | undefined): Promise<Set<string> | null> {
  const out = new Set<string>();
  const uid = String(userId ?? "").trim().toLowerCase();
  if (!uid) return out;
  const { map, ok } = await appStaffOrgMapChecked(tid);
  if (!ok) return null; // degraded org chain — membership UNKNOWN, not empty
  const entry = map.get(uid);
  if (!entry) return out;
  if (entry.orgBuId)   out.add(`org:bu:${entry.orgBuId}`);
  if (entry.orgDivId)  out.add(`org:div:${entry.orgDivId}`);
  if (entry.orgDeptId) out.add(`org:dept:${entry.orgDeptId}`);
  for (const rid of entry.roleAudienceIds) out.add(rid);
  return out;
}
/** uid (lowercase) → org sentinel ids, for whole-roster consumers like
 *  /user-list (the User Groups bulk-add matches people with these, so the
 *  snapshot uses the SAME membership the live rules enforce). */
export async function orgAudienceIdsByUser(tid: string): Promise<Map<string, string[]>> {
  const out = new Map<string, string[]>();
  for (const [uid, e] of await appStaffOrgMap(tid)) {
    const ids: string[] = [];
    if (e.orgBuId)   ids.push(`org:bu:${e.orgBuId}`);
    if (e.orgDivId)  ids.push(`org:div:${e.orgDivId}`);
    if (e.orgDeptId) ids.push(`org:dept:${e.orgDeptId}`);
    ids.push(...e.roleAudienceIds);
    if (ids.length) out.set(uid, ids);
  }
  return out;
}
// Hand access-control the live resolver (it can't import this module).
// Checked variant: null = resolution failed, so "except" audiences never
// mistake an outage for "member of nothing".
registerOrgAudienceResolver((tenantLabel, uid) => orgAudienceIdsForUserChecked(tenantLabelToTid(tenantLabel), uid));
async function appStaffOrgMap(tid: string): Promise<Map<string, StaffOrgEntry>> {
  return (await appStaffOrgMapChecked(tid)).map;
}
/** Like appStaffOrgMap but reports whether the core2 org-chain fetch actually
 *  succeeded. ok=false means the map is name-only (dept/div/BU blank because
 *  the DB was unreachable, NOT because the tenant has no org data) — callers
 *  that display or cache org columns must treat that as degraded. A degraded
 *  result is never cached here, so the next call retries. */
// Exported for the check:cache-guards bust-during-refresh regression tests.
export async function appStaffOrgMapChecked(tid: string): Promise<{ map: Map<string, StaffOrgEntry>; ok: boolean }> {
  const hit = staffOrgCache.get(tid);
  const now = Date.now();
  if (hit && hit.exp > now) return { map: hit.map, ok: true };
  // Serve-stale: a recently-expired roster map answers instantly (it was a
  // good map when cached) while ONE background rebuild refreshes it. Explicit
  // busts (invalidateStaffOrgCache — imports/user writes) DELETE the entry, so
  // they still force a fresh blocking read; only silent TTL expiry is bridged.
  if (hit && hit.exp + STAFF_ORG_STALE_GRACE_MS > now) {
    if (!staffOrgRefreshing.has(tid)) {
      staffOrgRefreshing.add(tid);
      void rebuildStaffOrgMapChecked(tid)
        .catch(() => { /* degraded rebuilds never cache; stale copy stays */ })
        .finally(() => staffOrgRefreshing.delete(tid));
    }
    return { map: hit.map, ok: true };
  }
  return rebuildStaffOrgMapChecked(tid);
}
const STAFF_ORG_STALE_GRACE_MS = 10 * 60_000;
const staffOrgRefreshing = new Set<string>();
async function rebuildStaffOrgMapChecked(tid: string): Promise<{ map: Map<string, StaffOrgEntry>; ok: boolean }> {
  const genAtStart = staffOrgGen; // see invalidateStaffOrgCache
  const map = new Map<string, StaffOrgEntry>();
  const [users, orgChain, aspRows] = await Promise.all([
    getActiveUsersByTenant(tid),
    (async () => {
      // Transient DB blips self-heal via withDbRetry; a FINAL failure must not
      // masquerade as "tenant has no org chain" — return ok:false so callers
      // treat the result as degraded and nothing caches it.
      try {
        return await withDbRetry(async () => {
        const jtMap   = new Map<string, { deptName: string; deptId: string; divId: string; divName: string; buName: string; buId: string; jtTitle: string }>();
        const deptMap = new Map<string, { title: string; divId: string }>();
        const divMap  = new Map<string, { divName: string; buName: string; buId: string }>();
        const pool2 = await getPool();
        const [jtCols2, deptCols2, cdCols2, roleCols2] = await Promise.all([
          tableColumns("JobTitle"),
          tableColumns("Department"),
          tableColumns("CompanyDivisions"),
          tableColumns("Roles"),
        ]);
        const buCols2   = cdCols2.has("BusinessUnitIdLookup") ? await tableColumns("BusinessUnit") : new Set<string>();
        const hasDeptId = jtCols2.has("DepartmentId");
        const hasDivId  = deptCols2.has("DivisionIdLookup");
        const hasBuFk   = cdCols2.has("BusinessUnitIdLookup") && buCols2.has("ID") && buCols2.has("Title");
        const hasShort  = cdCols2.has("ShortName");
        const jtTen     = jtCols2.has("TenantID")   ? " AND jt.TenantID  = @tid" : "";
        const cdTen     = cdCols2.has("TenantID")   ? " AND cd.TenantID  = @tid" : "";
        const depTen    = deptCols2.has("TenantID") ? " AND dep.TenantID = @tid" : "";
        // The three chain reads below (divisions, departments, job titles) are
        // independent SELECTs feeding three separate maps — start them all now
        // and await them as ONE batch. Serial awaits made every cold org-map
        // build pay three full round-trips back to back.
        const divRowsP = (cdCols2.has("ID") && cdCols2.has("Title"))
          ? pool2.request().input("tid", sql.NVarChar, tid).query(`
              SELECT CAST(cd.ID AS NVARCHAR(50)) AS DivId,
                     ${hasShort ? "COALESCE(NULLIF(LTRIM(RTRIM(cd.ShortName)),''),cd.Title)" : "cd.Title"} AS DivName,
                     ${hasBuFk ? "bu.Title" : "NULL"} AS BuName,
                     ${hasBuFk ? "CAST(bu.ID AS NVARCHAR(50))" : "NULL"} AS BuId
              FROM core2.dbo.CompanyDivisions cd
              ${hasBuFk ? "LEFT JOIN core2.dbo.BusinessUnit bu ON bu.ID = TRY_CAST(cd.BusinessUnitIdLookup AS BIGINT) AND bu.TenantID = cd.TenantID" : ""}
              WHERE 1=1${cdTen}`)
          : null;
        // ALL departments (with their division link), unconditionally — see the
        // block comments at each consumer below for why each read exists.
        //
        // Cross-tenant import fix: some imports write department_id values that
        // reference Department rows created under a different tenant's scope
        // (e.g. the import tool created the dept under one tenant then stored
        // the raw ID on users in another). The OR clause below ensures those
        // IDs still resolve to a readable name instead of falling back to
        // "Unassigned". Department IDs are identity-keyed globally, so there
        // is no ambiguity when resolving by ID alone.
        const depRowsP = (deptCols2.has("ID") && deptCols2.has("Title"))
          ? (() => {
              const tenantClause = deptCols2.has("TenantID")
                ? `dep.TenantID = @tid OR dep.ID IN (
                     SELECT TRY_CAST(ru.department_id AS BIGINT)
                     FROM rmoneapp.dbo.rmone_users ru
                     WHERE ru.tenant_id = @tid
                       AND ru.department_id IS NOT NULL AND ru.department_id <> ''
                   )`
                : "1=1";
              const depWhere =
                ` WHERE (${tenantClause})` +
                (deptCols2.has("Deleted") ? " AND (dep.Deleted = 0 OR dep.Deleted IS NULL)" : "");
              return pool2.request().input("tid", sql.NVarChar, tid).query(`
                  SELECT CAST(dep.ID AS NVARCHAR(50)) AS DepId,
                         dep.Title AS DeptName,
                         ${hasDivId ? "CAST(dep.DivisionIdLookup AS NVARCHAR(50))" : "NULL"} AS DivId
                  FROM core2.dbo.Department dep${depWhere}`);
            })()
          : null;
        // JobTitle → Department → Division chain (fallback source for people
        // with no per-user org links; also the only source of a JT's own dept).
        const jtRowsP = (hasDeptId && hasDivId && jtCols2.has("ID") && jtCols2.has("Title") && deptCols2.has("ID") && deptCols2.has("Title") && cdCols2.has("ID") && cdCols2.has("Title"))
          ? pool2.request().input("tid", sql.NVarChar, tid).query(`
              SELECT CAST(jt.ID AS NVARCHAR(50)) AS JtId,
                     jt.Title AS JtTitle,
                     CAST(dep.ID AS NVARCHAR(50)) AS DepId,
                     dep.Title AS DeptName,
                     CAST(cd.ID AS NVARCHAR(50)) AS DivId,
                     ${hasShort ? "COALESCE(NULLIF(LTRIM(RTRIM(cd.ShortName)),''),cd.Title)" : "cd.Title"} AS DivName,
                     ${hasBuFk ? "bu.Title" : "NULL"} AS BuName,
                     ${hasBuFk ? "CAST(bu.ID AS NVARCHAR(50))" : "NULL"} AS BuId
              FROM core2.dbo.JobTitle jt
              LEFT JOIN core2.dbo.Department dep
                ON dep.ID = TRY_CAST(NULLIF(CAST(jt.DepartmentId AS NVARCHAR(50)),'') AS BIGINT)${depTen}
              LEFT JOIN core2.dbo.CompanyDivisions cd
                ON cd.ID = TRY_CAST(NULLIF(CAST(dep.DivisionIdLookup AS NVARCHAR(50)),'') AS BIGINT)${cdTen}
              ${hasBuFk ? "LEFT JOIN core2.dbo.BusinessUnit bu ON bu.ID = TRY_CAST(cd.BusinessUnitIdLookup AS BIGINT) AND bu.TenantID = cd.TenantID" : ""}
              WHERE 1=1${jtTen}`)
          : null;
        // Tenant role catalog — backs the "role:<guid>" audience sentinels.
        // Fetched with the org chain (same freshness, same bust lifecycle) so
        // role-audience membership is exactly as live as BU/Division/Dept
        // membership. Deleted roles drop out, so their sentinels stop matching.
        const roleRowsP = (roleCols2.has("Id") && roleCols2.has("Name"))
          ? (() => {
              // Role membership is a NAME bridge, so an unscoped read would
              // merge same-named roles from EVERY tenant into this tenant's
              // audience map — a tenant-isolation hole, not a degraded mode.
              // Roles table present but unscopable = outage (ok:false via the
              // catch below); NEVER fall back to an unscoped query. (A schema
              // with no Roles table at all stays ok:true with an empty bridge —
              // role sentinels simply match nobody, like deleted roles.)
              if (!roleCols2.has("TenantID")) {
                throw new Error("core2.dbo.Roles has no TenantID column — cannot tenant-scope the role-audience bridge");
              }
              return pool2.request().input("tid", sql.NVarChar, tid).query(`
                SELECT CAST(Id AS NVARCHAR(50)) AS Id, Name
                FROM core2.dbo.Roles WITH (NOLOCK)
                WHERE TenantID = @tid${roleCols2.has("Deleted") ? " AND (Deleted = 0 OR Deleted IS NULL)" : ""}`);
            })()
          : null;
        // ALL divisions (with their BU), unconditionally — NOT just the ones
        // some JobTitle chain reaches. Per-user divisionId must resolve even
        // when no job title references the division.
        if (divRowsP) {
          const rows2 = (((await divRowsP).recordset) ?? []) as Record<string, unknown>[];
          for (const row of rows2) {
            const divId = String(row.DivId  ?? "").trim();
            const dv    = String(row.DivName ?? "").trim();
            const bu    = String(row.BuName  ?? "").trim();
            const buId  = String(row.BuId    ?? "").trim().toLowerCase();
            if (divId && dv) divMap.set(divId.toLowerCase(), { divName: dv, buName: bu, buId });
          }
        }
        // ALL departments (with their division link), unconditionally. The old
        // shape only collected departments reachable from a JobTitle row — a
        // tenant whose job titles carried no DepartmentId had an EMPTY deptMap,
        // so the per-user departmentId fallback could never resolve and every
        // staff row displayed "Unassigned" even though the users table stored
        // the correct department id for each person.
        //
        // Cross-tenant import fix: some imports write department_id values that
        // reference Department rows created under a different tenant's scope
        // (e.g. the import tool created the dept under one tenant then stored
        // the raw ID on users in another). The OR clause below ensures those
        // IDs still resolve to a readable name instead of falling back to
        // "Unassigned". Department IDs are identity-keyed globally, so there
        // is no ambiguity when resolving by ID alone.
        if (depRowsP) {
          const rows3 = (((await depRowsP).recordset) ?? []) as Record<string, unknown>[];
          for (const row of rows3) {
            const depId = String(row.DepId ?? "").trim().toLowerCase();
            const dn    = String(row.DeptName ?? "").trim();
            const dvId  = String(row.DivId ?? "").trim();
            if (depId && dn) deptMap.set(depId, { title: dn, divId: dvId });
          }
        }
        // JobTitle → Department → Division chain (fallback source for people
        // with no per-user org links; also the only source of a JT's own dept).
        if (jtRowsP) {
          const rows = (((await jtRowsP).recordset) ?? []) as Record<string, unknown>[];
          for (const row of rows) {
            const jtId = String(row.JtId  ?? "").trim().toLowerCase();
            const depId= String(row.DepId ?? "").trim().toLowerCase();
            const divId= String(row.DivId ?? "").trim();
            const dn   = String(row.DeptName ?? "").trim();
            const dv   = String(row.DivName  ?? "").trim();
            const bu   = String(row.BuName   ?? "").trim();
            const buId = String(row.BuId     ?? "").trim().toLowerCase();
            const jtT  = String(row.JtTitle  ?? "").trim();
            if (jtId)  jtMap.set(jtId, { deptName: dn, deptId: depId, divId, divName: dv, buName: bu, buId, jtTitle: jtT });
          }
        }
        const roleIdx = roleRowsP
          ? buildRoleAudienceIndex(((((await roleRowsP).recordset) ?? []) as Record<string, unknown>[])
              .map((r) => ({ id: r.Id, name: r.Name })))
          : new Map<string, string[]>();
        return { jtMap, deptMap, divMap, roleIdx, ok: true };
        });
      } catch (e) {
        console.warn(`[appStaffOrgMap] org-chain fetch failed for tenant ${tid}: ${String(e)}`);
        return {
          jtMap:   new Map<string, { deptName: string; deptId: string; divId: string; divName: string; buName: string; buId: string; jtTitle: string }>(),
          deptMap: new Map<string, { title: string; divId: string }>(),
          divMap:  new Map<string, { divName: string; buName: string; buId: string }>(),
          roleIdx: new Map<string, string[]>(),
          ok: false,
        };
      }
    })(),
    (async () => {
      // Fallback name source: core2 AspNetUsers. Some tenants have team members
      // whose GUIDs exist only in AspNetUsers (older imports wrote core2 but
      // never the app-DB users table). Without this supplement those GUIDs
      // resolve to no entry and every screen falls back to a "User 25FB43B2"
      // placeholder even though a real name exists in core2.
      try {
        const pool3 = await getPool();
        const uCols = await tableColumns("AspNetUsers");
        if (!uCols.has("Id")) return [] as Record<string, unknown>[];
        const strCol = (c: string, alias: string) =>
          uCols.has(c) ? `CAST(u.[${c}] AS NVARCHAR(400)) AS [${alias}]` : `NULL AS [${alias}]`;
        const divCol  = uCols.has("DivisionLookup") ? "DivisionLookup"
                      : uCols.has("DivisionIDLookup") ? "DivisionIDLookup" : null;
        const deptCol = uCols.has("DepartmentLookup") ? "DepartmentLookup"
                      : uCols.has("DepartmentIDLookup") ? "DepartmentIDLookup" : null;
        const tenGuard = uCols.has("TenantID") ? "WHERE u.TenantID = @tid" : "WHERE 1=1";
        const delGuard = uCols.has("Deleted") ? " AND (u.Deleted = 0 OR u.Deleted IS NULL)" : "";
        const r3 = await pool3.request().input("tid", sql.NVarChar, tid).query(`
          SELECT CAST(u.Id AS NVARCHAR(50)) AS Id,
                 ${strCol("Name", "Name")},
                 ${strCol("UserName", "UserName")},
                 ${strCol("Email", "Email")},
                 ${strCol("Title", "Title")},
                 ${uCols.has("JobTitleLookup") ? "CAST(u.[JobTitleLookup] AS NVARCHAR(50))" : "NULL"} AS JobTitleLookup,
                 ${divCol ? `CAST(u.[${divCol}] AS NVARCHAR(50))` : "NULL"} AS DivisionLookup,
                 ${deptCol ? `CAST(u.[${deptCol}] AS NVARCHAR(50))` : "NULL"} AS DepartmentLookup
          FROM core2.dbo.AspNetUsers u WITH (NOLOCK)
          ${tenGuard}${delGuard}`);
        return (r3.recordset ?? []) as Record<string, unknown>[];
      } catch { return [] as Record<string, unknown>[]; }
    })(),
  ]);
  for (const u of users) {
    const jtId   = (u.jobTitleId   || "").toLowerCase();
    const divId  = (u.divisionId   || "").toLowerCase();
    const deptId = (u.departmentId || "").toLowerCase();
    const fromJt  = jtId  ? orgChain.jtMap.get(jtId)  : undefined;
    // Per-user org links WIN over the JobTitle-derived chain. A job title is
    // shared by people across DIFFERENT departments (one JT-level link cannot
    // be right for all of them — imports link a JT to whichever department it
    // was first seen with), while users.departmentId / divisionId are stamped
    // per PERSON by imports and staff-assignment edits. The JT chain stays as
    // the fallback for people with no per-user link (older imports).
    const fromUserDept = deptId ? orgChain.deptMap.get(deptId) : undefined;
    const dept = fromUserDept?.title || fromJt?.deptName || "";
    // Division precedence mirrors the Staff card: per-user DivisionLookup
    // first, then the division of the person's own department, then JT chain.
    const effDivKey = divId || (fromUserDept?.divId || "").toLowerCase() || (fromJt?.divId || "").toLowerCase();
    const fromDiv = effDivKey ? orgChain.divMap.get(effDivKey) : undefined;
    const divName = fromDiv?.divName || fromJt?.divName || "";
    const buName  = fromDiv?.buName  || fromJt?.buName  || "";
    // Placeholder-aware display title: real title → catalogue title → role.
    const jtTitle = fromJt?.jtTitle || "";
    const dispTitle =
      (!isTitlePlaceholder(u.title) ? (u.title || "").trim() : "") ||
      (!isTitlePlaceholder(jtTitle) ? jtTitle : "") ||
      (!isTitlePlaceholder(u.role) ? (u.role || "").trim() : "") ||
      (u.title || "").trim() || jtTitle || (u.role || "").trim();
    map.set(u.id.toLowerCase(), {
      id: u.id, name: u.name || "", username: u.username || "",
      email: (u as unknown as Record<string, unknown>).email as string || "",
      enabled: u.enabled !== false,
      title: dispTitle, role: u.role || "",
      jobTitleId: u.jobTitleId || "", divisionId: u.divisionId || "", departmentId: u.departmentId || "",
      dept, divName, buName,
      employeeType: (u.employeeType || "").trim(),
      // Resolved org ids mirror the name precedence above: per-user links
      // first, JobTitle chain as fallback.
      orgBuId:   (fromDiv?.buId || fromJt?.buId || "").toLowerCase(),
      orgDivId:  (effDivKey || "").toLowerCase(),
      orgDeptId: (deptId || fromJt?.deptId || "").toLowerCase(),
      // Role sentinels via the name bridge: every tenant Roles row whose
      // normalized Name equals this user's displayed role text.
      roleAudienceIds: orgChain.roleIdx.get(normRoleName(u.role)) ?? [],
    });
  }
  // Supplement: GUIDs present in core2 AspNetUsers but missing from the app-DB
  // users table (legacy/import gaps). App-DB rows always win; these only fill
  // holes so allocation rows referencing such GUIDs display real names instead
  // of "User XXXXXXXX" placeholders.
  const GUID_RE_ORG = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  // "User 25FB43B2"-style placeholder minted by older imports when the only
  // identifier in the source sheet was a GUID.
  const PLACEHOLDER_NAME_RE = /^User [0-9A-F]{8}$/i;
  for (const row of aspRows) {
    const id = String(row.Id ?? "").trim();
    if (!id) continue;
    const key = id.toLowerCase();
    const rawName = String(row.Name ?? "").trim();
    const uname   = String(row.UserName ?? "").trim();
    const email   = String(row.Email ?? "").trim() || (uname.includes("@") ? uname : "");
    // GUID-as-name guard: a bare GUID is never a display name — fall through
    // to the username/email so the card shows something readable.
    const name = rawName && !GUID_RE_ORG.test(rawName) ? rawName
               : uname && !GUID_RE_ORG.test(uname) ? uname
               : email && !GUID_RE_ORG.test(email) ? email : "";
    const existing = map.get(key);
    if (existing) {
      // App-DB row wins — EXCEPT when it carries a minted placeholder ("User
      // 25FB43B2"), a bare GUID, or no name at all while core2 knows the real
      // one. Upgrade in place so the placeholder never reaches the UI.
      const exName = existing.name.trim();
      const exBad = !exName || GUID_RE_ORG.test(exName) || PLACEHOLDER_NAME_RE.test(exName);
      if (exBad && name && !PLACEHOLDER_NAME_RE.test(name)) existing.name = name;
      if (!existing.title.trim() && String(row.Title ?? "").trim()) existing.title = String(row.Title ?? "").trim();
      continue;
    }
    const jtId    = String(row.JobTitleLookup ?? "").trim().toLowerCase();
    const divIdA  = String(row.DivisionLookup ?? "").trim();
    const deptIdA = String(row.DepartmentLookup ?? "").trim().toLowerCase();
    const fromJt  = jtId ? orgChain.jtMap.get(jtId) : undefined;
    // Same precedence as the app-DB path above: the row's own department /
    // division lookups win, the JobTitle chain is the fallback.
    const fromUserDeptA = deptIdA ? orgChain.deptMap.get(deptIdA) : undefined;
    const effDivKeyA = divIdA.toLowerCase() || (fromUserDeptA?.divId || "").toLowerCase() || (fromJt?.divId || "").toLowerCase();
    const fromDiv = effDivKeyA ? orgChain.divMap.get(effDivKeyA) : undefined;
    map.set(key, {
      id, name, username: uname, email,
      // There is no canonical app-user row for this legacy-only identity.
      enabled: true,
      // Title precedence mirrors the app-DB path: stored title string first,
      // then the JobTitle catalogue name resolved via JobTitleLookup.
      title: String(row.Title ?? "").trim() || fromJt?.jtTitle || "",
      role: "",
      jobTitleId: jtId, divisionId: divIdA, departmentId: deptIdA,
      dept:    fromUserDeptA?.title || fromJt?.deptName || "",
      divName: fromDiv?.divName || fromJt?.divName || "",
      buName:  fromDiv?.buName  || fromJt?.buName  || "",
      // core2 AspNetUsers has no employee-type column; only app-DB rows carry it.
      employeeType: "",
      orgBuId:   (fromDiv?.buId || fromJt?.buId || "").toLowerCase(),
      orgDivId:  (effDivKeyA || "").toLowerCase(),
      orgDeptId: (deptIdA || fromJt?.deptId || "").toLowerCase(),
      // core2-only identities carry no app-DB role text — no role audiences.
      roleAudienceIds: [],
    });
  }
  // Never cache a degraded map — a transient DB failure would otherwise pin
  // blank org columns ("—" everywhere) for every consumer for the full TTL.
  // genAtStart: never cache a map built before an explicit bust landed.
  if (orgChain.ok && genAtStart === staffOrgGen) staffOrgCache.set(tid, { map, exp: Date.now() + STAFF_ORG_TTL_MS });
  return { map, ok: orgChain.ok };
}

// ── Title-keyed rate fallback map (cached, tenant-scoped) ────────────────────
// The team-card rate joins key off the assignment row's JobTitleLookup /
// rwi.Title. Rows repaired from GUID-only imports have neither, so those joins
// return NULL even though the person's job title is known from the org map.
// This map lets the loop fall back to a rate looked up BY TITLE NAME:
// Roles.Name → BillingRate wins (the Billing Rates screen is keyed by role
// name), then JobTitle.Title → EmpCostRate (internal cost catalogue).
const titleRateCache = new Map<string, { map: Map<string, number>; exp: number }>();
const TITLE_RATE_TTL_MS = 5 * 60_000;
const TITLE_RATE_STALE_GRACE_MS = 10 * 60_000;
const titleRateRefreshing = new Set<string>();
async function titleRateMap(tid: string): Promise<Map<string, number>> {
  const hit = titleRateCache.get(tid);
  const now = Date.now();
  if (hit && hit.exp > now) return hit.map;
  // Serve-stale: rate fallbacks tolerate a briefly-stale catalogue far better
  // than every team read stalling a round-trip on silent TTL expiry.
  if (hit && hit.exp + TITLE_RATE_STALE_GRACE_MS > now) {
    if (!titleRateRefreshing.has(tid)) {
      titleRateRefreshing.add(tid);
      void rebuildTitleRateMap(tid)
        .catch(() => { /* best-effort — stale copy stays */ })
        .finally(() => titleRateRefreshing.delete(tid));
    }
    return hit.map;
  }
  return rebuildTitleRateMap(tid);
}
async function rebuildTitleRateMap(tid: string): Promise<Map<string, number>> {
  const map = new Map<string, number>();
  try {
    const pool = await getPool();
    const [roleCols, jtCols] = await Promise.all([tableColumns("Roles"), tableColumns("JobTitle")]);
    // JobTitle.EmpCostRate first so Roles.BillingRate can overwrite (higher precedence).
    if (jtCols.has("Title") && jtCols.has("EmpCostRate")) {
      const ten = jtCols.has("TenantID") ? " WHERE TenantID = @tid" : "";
      const r = await pool.request().input("tid", sql.NVarChar, tid)
        .query(`SELECT Title, EmpCostRate FROM core2.dbo.JobTitle WITH (NOLOCK)${ten}`);
      for (const row of r.recordset ?? []) {
        const k = String(row.Title ?? "").trim().toLowerCase();
        const v = Number(row.EmpCostRate) || 0;
        if (k && v > 0 && !map.has(k)) map.set(k, v);
      }
    }
    if (roleCols.has("Name") && roleCols.has("BillingRate")) {
      const guards: string[] = [];
      if (roleCols.has("TenantID")) guards.push("TenantID = @tid");
      if (roleCols.has("Deleted"))  guards.push("(Deleted = 0 OR Deleted IS NULL)");
      const w = guards.length ? ` WHERE ${guards.join(" AND ")}` : "";
      const r = await pool.request().input("tid", sql.NVarChar, tid)
        .query(`SELECT Name, BillingRate FROM core2.dbo.Roles WITH (NOLOCK)${w}`);
      for (const row of r.recordset ?? []) {
        const k = String(row.Name ?? "").trim().toLowerCase();
        const v = Number(row.BillingRate) || 0;
        if (k && v > 0) map.set(k, v);
      }
    }
  } catch { /* best-effort — rates fall back to defaultRate */ }
  titleRateCache.set(tid, { map, exp: Date.now() + TITLE_RATE_TTL_MS });
  return map;
}

// RWI.Title is supposed to hold the assignment ROLE name ("Project Manager"),
// but some legacy imports wrote the project's ticket ID into it (e.g.
// "PMM-26-001"). A ticket is never a valid role — blank it so team cards and
// allocation grids show an empty role instead of a meaningless ticket string.
const TICKET_AS_ROLE_RE = /^(PMM|OPM|LEM|COM)-[A-Za-z0-9][A-Za-z0-9-]*$/i;
export function cleanRoleName(role: unknown, projectId?: string): string {
  const r = String(role ?? "").trim();
  if (!r) return "";
  if (projectId && r.toLowerCase() === String(projectId).trim().toLowerCase()) return "";
  if (TICKET_AS_ROLE_RE.test(r)) return "";
  return r;
}

// Map an RM ONE module code to the core2 table that backs it. Only the modules
// needed by the in-scope screens are supported; others return empty (the screen
// degrades gracefully rather than erroring).
const MODULE_TABLE: Record<string, string> = {
  PMM: "PMM",
  OPM: "Opportunity",
  LEM: "Lead",
};

/**
 * Every raw field the record detail page can possibly surface for a module —
 * RECORD_FIELDS intersected with the module table's LIVE columns (exactly the
 * `selectable` set getRecordDetail SELECTs into rawFields). Used by Settings →
 * Display Defaults so an admin can configure record-page field defaults
 * without opening a record. Proper-cased names straight from RECORD_FIELDS,
 * so keys match rawFields keys on the frontend.
 */
export async function detailFieldCatalog(mod: "PMM" | "OPM" | "LEM"): Promise<string[]> {
  const live = await tableColumns(MODULE_TABLE[mod]);
  return [...new Set(RECORD_FIELDS.filter((f) => live.has(f)))];
}

// Resolve the module type from any TicketId format. OPM → opportunity,
// LEM → lead, EVERYTHING ELSE (PMM, PRJ-2024-001, custom client IDs, …) → PMM.
// This lets clients use their own project-ID conventions (e.g. "PRJ-2024-001")
// without breaking the lookup logic.  Returns null only for an empty/blank id.
//
// Custom OPPORTUNITY IDs (user typed their own Opp ID at create time, e.g.
// "bid-2026-04") cannot be recognised by prefix — they live in the tenant-scoped
// customOppTickets cache (loaded from core2.dbo.Opportunity, refreshed on a TTL
// and updated synchronously on create). Callers that pass `tid` get correct OPM
// routing for those; callers without tid keep the historical prefix-only logic.
// (exported for the schedule-window gate tests)
export function resolveTicketMod(id: string, tid?: string): "PMM" | "OPM" | "LEM" | null {
  const u = (id ?? "").trim().toUpperCase();
  if (!u) return null;
  if (u.startsWith("OPM")) return "OPM";
  if (u.startsWith("LEM")) return "LEM";
  if (tid && customOppTickets.has(`${tid}|${u.toLowerCase()}`)) return "OPM";
  if (tid && customLeadTickets.has(`${tid}|${u.toLowerCase()}`)) return "LEM";
  return "PMM"; // PMM, PRJ, or any other custom project prefix
}

// ── Custom (non-OPM-prefixed) opportunity TicketIds, tenant-scoped ──────────
// Key format: `${tenantId}|${ticketIdLowercase}`. Loaded lazily with a TTL so
// resolveTicketMod (sync, called everywhere) can consult it without a DB trip.
// createRecordRds registers new custom opp IDs immediately, so routing is
// correct the instant an opportunity is created — the TTL reload only matters
// after a server restart.
let customOppTickets = new Set<string>();
// Same idea for LEADS: imports may assign a user-supplied lead ID with no LEM
// prefix. Loaded by the same loader below (one round trip); checked AFTER the
// opp cache so a (historical) ID present in both keeps its old OPM routing.
let customLeadTickets = new Set<string>();
let customOppLoadedAt = 0;
let customOppLoading: Promise<boolean> | null = null;
const CUSTOM_OPP_TTL_MS = 5 * 60_000;
// The server runs multiple cluster workers, each with its own copy of this
// cache. registerCustomOppTicket only updates the worker that handled the
// create — so a lookup landing on a sibling worker would mis-route a brand-new
// custom opp ID to PMM until the TTL reload. Miss-triggered refresh closes that
// gap: when the caller is about to resolve a ticket with no standard prefix
// that isn't in the cache, force a reload (bounded to once per 5s so custom
// PMM tickets, which legitimately never appear here, can't hammer the DB).
let customOppForcedAt = 0;
const CUSTOM_OPP_FORCE_MIN_MS = 5_000;

function hasStandardPrefix(u: string): boolean {
  return u.startsWith("OPM") || u.startsWith("LEM") || u.startsWith("PMM");
}

// Single-flight loader for BOTH custom sets, shared by the read-path ensure
// below and the save-path trusted ensure. Resolves TRUE on a successful set
// swap and FALSE on failure — it never rejects, because read-path callers
// deliberately tolerate failures and keep running on the stale sets, while
// save-path callers use the boolean to fail CLOSED instead of trusting the
// resolver's silent PMM default.
function startCustomOppLoad(): Promise<boolean> {
  if (customOppLoading) return customOppLoading;
  const p = (async () => {
    try {
      const pool = await getPool();
      // One round trip loads BOTH custom sets. Lead rows additionally exclude
      // PMM%/OPM% (a lead ticket can never legitimately carry those prefixes;
      // letting junk through would hijack standard-prefixed lookups because the
      // lead cache is consulted before the PMM default).
      const r = await pool.request().query(
        `SELECT TenantID, TicketId, 'OPM' AS Mod FROM core2.dbo.Opportunity
         WHERE TicketId IS NOT NULL AND LTRIM(RTRIM(TicketId)) <> ''
           AND UPPER(TicketId) NOT LIKE 'OPM%'
         UNION ALL
         SELECT TenantID, TicketId, 'LEM' AS Mod FROM core2.dbo.Lead
         WHERE TicketId IS NOT NULL AND LTRIM(RTRIM(TicketId)) <> ''
           AND UPPER(TicketId) NOT LIKE 'LEM%'
           AND UPPER(TicketId) NOT LIKE 'PMM%'
           AND UPPER(TicketId) NOT LIKE 'OPM%'`,
      );
      const nextOpp = new Set<string>();
      const nextLead = new Set<string>();
      for (const row of (r.recordset ?? []) as Record<string, unknown>[]) {
        const t = String(row.TicketId ?? "").trim().toLowerCase();
        const ten = String(row.TenantID ?? "").trim();
        if (!t || !ten) continue;
        (String(row.Mod) === "LEM" ? nextLead : nextOpp).add(`${ten}|${t}`);
      }
      customOppTickets = nextOpp;
      customLeadTickets = nextLead;
      customOppLoadedAt = Date.now();
      return true;
    } catch (e) {
      console.warn(`[custom-opp-tickets] load failed: ${String(e)}`);
      return false;
    }
  })();
  customOppLoading = p;
  void p.finally(() => { if (customOppLoading === p) customOppLoading = null; });
  return p;
}

// (exported for the schedule-window gate tests)
export async function ensureCustomOppTickets(tid?: string, ticketId?: string): Promise<void> {
  const fresh = Date.now() - customOppLoadedAt < CUSTOM_OPP_TTL_MS;
  // A ticket with no standard prefix that is absent from the cached set may be
  // a brand-new custom opp ID (e.g. registered on a sibling cluster worker).
  // Resolving it against a stale or missing cache would mis-route the write to
  // PMM, so such lookups must always wait for fresh data — regardless of TTL.
  let unknownCustomTicket = false;
  if (tid && ticketId) {
    const u = ticketId.trim().toUpperCase();
    const k = `${tid}|${u.toLowerCase()}`;
    unknownCustomTicket = !!u && !hasStandardPrefix(u) &&
      !customOppTickets.has(k) && !customLeadTickets.has(k);
  }
  const force = fresh && unknownCustomTicket &&
    Date.now() - customOppForcedAt >= CUSTOM_OPP_FORCE_MIN_MS;
  if (fresh && !force) return;
  // Block when correctness demands fresh data: first-ever load, a forced
  // cache-miss refresh, or a TTL-expired lookup of an unknown custom ticket.
  // Standard PMM/OPM/LEM-prefixed tickets (the vast majority) never block on a
  // TTL-expired refresh — they get the stale-while-revalidate fast path.
  // They don't block on the FIRST-EVER load either (a ~2s cross-tenant
  // Opportunity+Lead scan): OPM/LEM prefixes never consult the custom sets at
  // all, and the rare PMM-prefixed custom opp/lead ID is covered by the
  // no-row retry in getRecordDetail, which awaits this load and re-resolves.
  // Callers without a ticketId still block until the sets exist.
  const standardTicket = !!ticketId && hasStandardPrefix(ticketId.trim().toUpperCase());
  const mustBlock = (customOppLoadedAt === 0 && !standardTicket) || force || (!fresh && unknownCustomTicket);
  if (customOppLoading) {
    if (mustBlock) await customOppLoading;
    return;
  }
  if (force) customOppForcedAt = Date.now();
  const load = startCustomOppLoad();
  // Stale-while-revalidate: when a cache already exists (customOppLoadedAt > 0)
  // and this is just a TTL-expired refresh, DON'T block the caller (e.g. a
  // field save) on a full Opportunity scan over the slow DB link — return
  // immediately with the stale set and let the refresh complete in background.
  if (mustBlock) await load;
}

// SAVE-path variant of ensureCustomOppTickets for correctness-critical module
// resolution (the schedule-window validation gate). Returns TRUE only when
// resolving this ticket's module against the custom sets is trustworthy:
//   - standard PMM/OPM/LEM prefix (the sets are never consulted), or
//   - a positive hit in the opp/lead set, or
//   - a SUCCESSFUL load completed for THIS lookup with the id still absent —
//     a true negative, so the resolver's PMM default is correct.
// Returns FALSE when the answer would rest on a failed or skipped load, and
// callers must then fail CLOSED — never trust the silent PMM default. Two
// deliberate differences from the read-path ensure above:
//   1. the 5s force-throttle (an anti-hammer for the hot sync resolver) NEVER
//      skips this lookup — a distinct unknown record always gets a real load;
//   2. load failures are surfaced (the read path swallows them and runs on
//      the stale sets, which is fine for display routing but not for a gate).
// Concurrent loads still dedupe: an in-flight load is JOINED, and because a
// joined load may have queried before this save arrived, a still-unknown id
// afterwards gets ONE fresh load of its own before the verdict.
// (exported for the schedule-window gate tests)
export async function ensureCustomTicketsTrusted(tid?: string, ticketId?: string): Promise<boolean> {
  const u = (ticketId ?? "").trim().toUpperCase();
  if (u && hasStandardPrefix(u)) return true;
  if (!u || !tid) {
    // Nothing to look up — trust only a cache that has loaded successfully
    // at least once, otherwise demand one successful load now.
    if (customOppLoadedAt !== 0) return true;
    return await (customOppLoading ?? startCustomOppLoad());
  }
  const k = `${tid}|${u.toLowerCase()}`;
  const known = () => customOppTickets.has(k) || customLeadTickets.has(k);
  if (known()) return true;
  for (let attempt = 0; attempt < 2; attempt++) {
    const inFlight = customOppLoading;
    const ownLoad = inFlight == null;
    const ok = await (inFlight ?? startCustomOppLoad());
    if (known()) return true;
    if (!ok) return false; // load failed — absence proves nothing
    if (ownLoad) return true; // our own completed load: trustworthy negative
    // Joined a load that may predate this save — retry with a fresh one.
  }
  return false; // repeated joins without a verdict (racing savers) — fail closed
}

function registerCustomOppTicket(tid: string, ticketId: string): void {
  const t = (ticketId || "").trim().toLowerCase();
  if (t && tid && !t.startsWith("opm")) customOppTickets.add(`${tid}|${t}`);
}

// Custom (non-LEM-prefixed) lead IDs — same idea as registerCustomOppTicket.
// Standard-prefixed IDs are excluded entirely (mirrors the loader's filter):
// the lead cache is consulted before the PMM default in resolveTicketMod, so
// letting a PMM/OPM-prefixed key in would hijack standard routing.
function registerCustomLeadTicket(tid: string, ticketId: string): void {
  const t = (ticketId || "").trim().toLowerCase();
  if (t && tid && !hasStandardPrefix(t.toUpperCase())) customLeadTickets.add(`${tid}|${t}`);
}

